ST.xhtml:p:
IF g_bFrontSustainEnable THEN
  FBFrontSustainPower();
  FBFrontSustainJogControl();
  FBFrontSustainFollowControl();
  FBFrontSustainAct();
  FBFrontSustainInchControl();
  FBFrontSustainAbsolute();
  FBFrontSustainHome();
  FBFrontSustainVelAdd();


  bAxis1ErrorAlarm :=  Axis_Sustain4.NCTOPLC.POWERPOSWARN OR Axis_Sustain4.NCTOPLC.POWERNEGWARN 
     OR Axis_Sustain4.NCTOPLC.ERRORCODE <>0;

	bAxis2ErrorAlarm :=  Axis_Sustain5.NCTOPLC.POWERPOSWARN OR Axis_Sustain5.NCTOPLC.POWERNEGWARN 
     OR Axis_Sustain5.NCTOPLC.ERRORCODE <>0;

	bAxis3ErrorAlarm :=  Axis_Sustain6.NCTOPLC.POWERPOSWARN OR Axis_Sustain6.NCTOPLC.POWERNEGWARN 
     OR Axis_Sustain6.NCTOPLC.ERRORCODE <>0;

     bAxis4ErrorAlarm :=  AntiRejection2.NCTOPLC.POWERPOSWARN OR AntiRejection2.NCTOPLC.POWERNEGWARN 
     OR AntiRejection2.NCTOPLC.ERRORCODE <>0;






  IF bAxis1ErrorAlarm AND g_bPlcResetBuffer THEN
    g_Sustain4Reset.Execute := TRUE;
  ELSE
    g_Sustain4Reset.Execute := FALSE;
  END_IF;

   IF bAxis2ErrorAlarm AND g_bPlcResetBuffer THEN
    g_Sustain5Reset.Execute := TRUE;
  ELSE
    g_Sustain5Reset.Execute := FALSE;
  END_IF;

   IF bAxis3ErrorAlarm AND g_bPlcResetBuffer THEN
    g_Sustain6Reset.Execute := TRUE;
  ELSE
    g_Sustain6Reset.Execute := FALSE;
  END_IF;

   IF bAxis4ErrorAlarm AND g_bPlcResetBuffer THEN
    g_AntiRejection2Reset.Execute := TRUE;
  ELSE
    g_AntiRejection2Reset.Execute := FALSE;
  END_IF;
END_IF;



FBFrontSustainFollowControlExt();
FBFrontSustainDown();
